package org.slavicmyths.client;
import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.client.model.geom.ModelPart;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import org.slavicmyths.finist.*;
@EventBusSubscriber(modid="slavicmyths",value=Dist.CLIENT)
public final class BrightFalconClient {
 @EventBusSubscriber(modid="slavicmyths",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)public static class Registration{
 @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers e){e.registerEntityRenderer(FinistContent.FINIST.get(),HeroRenderer::new);e.registerEntityRenderer(FinistContent.KARTAUS.get(),BossRenderer::new);e.registerEntityRenderer(FinistContent.BANNER.get(),PropRenderer::new);e.registerEntityRenderer(FinistContent.ANCHOR.get(),PropRenderer::new);}
 @SubscribeEvent public static void eggColor(RegisterColorHandlersEvent.Item e){e.register((s,t)->-1,net.minecraft.core.registries.BuiltInRegistries.ITEM.get(FinistContent.id("kartaus_spawn_egg")));}}
 public static Vec3 birdOffset(FinistEntity f,float partial){double t=f.birdAge(partial);if(f.morphed())return new Vec3(0,.3,0);if(f.bird()==1){double a=t*Math.PI/40;return new Vec3(Math.sin(a)*11,5.5+Math.sin(t*.1)*.3,Math.cos(a)*11);}if(f.bird()==4){var a=f.level().getEntity(f.anchorId());return a==null?new Vec3(.5,2.7,0):a.position().add(0,2.7,0).subtract(f.position());}if(f.bird()==2){var target=f.level().getEntity(f.birdTarget());if(target!=null){double blend=t<16?Math.clamp(t/16,0,1):Math.clamp((26-t)/10,0,1);return new Vec3(.48,1.5,-.2).lerp(target.position().add(0,1.2,0).subtract(f.position()),blend).add(0,Math.sin(Math.min(t,16)/16*Math.PI)*3,0);}}if(f.bird()==3)return new Vec3(Math.sin(t*.15)*3,1.8,-2);double a=Math.toRadians(-f.getYRot());return new Vec3(.48*Math.cos(a)+.2*Math.sin(a),1.5,.48*Math.sin(a)-.2*Math.cos(a));}
 public static class HeroRenderer extends MobRenderer<FinistEntity,FinistModel<FinistEntity>>{
 private final ModelPart falcon=FalconMesh.create();public HeroRenderer(EntityRendererProvider.Context c){super(c,new FinistModel<>(FinistMesh.create(),false),.4F);}@Override public ResourceLocation getTextureLocation(FinistEntity e){return FinistContent.id("textures/entity/finist.png");}@Override protected float getFlipDegrees(FinistEntity e){return 0;}
 @Override public void render(FinistEntity e,float yaw,float partial,PoseStack p,MultiBufferSource buf,int light){super.render(e,yaw,partial,p,buf,light);if(e.bird()==5&&!e.morphed())return;var at=birdOffset(e,partial);p.pushPose();p.translate(at.x,at.y,at.z);p.mulPose(Axis.YP.rotationDegrees(180-yaw));float scale=e.morphed()?1.33F:.85F;p.scale(-scale,-scale,scale);p.translate(0,-1.5,0);falcon.getAllParts().forEach(ModelPart::resetPose);var body=falcon.getChild("body");boolean fly=e.bird()!=0||e.morphed();body.getChild("right_wing").zRot=fly?(float)Math.sin((e.tickCount+partial)*.8)*.9F:1.15F;body.getChild("left_wing").zRot=-body.getChild("right_wing").zRot;if(e.bird()==4){body.getChild("right_wing").zRot=.3F;body.getChild("left_wing").zRot=-.3F;}if(e.morphed())body.xRot=.45F;falcon.render(p,buf.getBuffer(RenderType.entityCutoutNoCull(FinistContent.id("textures/entity/"+(e.morphed()?"finist_morph_falcon":"finist_falcon")+".png"))),light,OverlayTexture.NO_OVERLAY,-1);p.popPose();
 if(e.markTarget()!=0)targetMark(e,e.markTarget(),p,buf,partial,0xEACB67);for(int id:e.watchIds())if(id!=0)targetMark(e,id,p,buf,partial,0xD0A64E);if(e.bird()==4){var anchor=e.level().getEntity(e.anchorId());if(anchor!=null){var to=anchor.position().add(0,.6,0).subtract(e.position());for(int n=0;n<12;n++){var q=at.lerp(to,n/11D);ring(p,buf,q.x,q.y,q.z,.07,0x9C5CCC,.8F);}}}}
 }
 private static void targetMark(FinistEntity e,int id,PoseStack p,MultiBufferSource b,float partial,int color){var t=e.level().getEntity(id);var me=Minecraft.getInstance().player;if(t==null||me==null||me.distanceTo(t)>20||!me.hasLineOfSight(t))return;var q=t.position().subtract(e.position());ring(p,b,q.x,q.y+t.getBbHeight()+.3,q.z,.35,color,.6F);}
 public static class BossRenderer extends MobRenderer<KartausEntity,FinistModel<KartausEntity>>{public BossRenderer(EntityRendererProvider.Context c){super(c,new FinistModel<>(KartausMesh.create(),true),.7F);}@Override public ResourceLocation getTextureLocation(KartausEntity e){return FinistContent.id("textures/entity/kartaus.png");}@Override protected float getFlipDegrees(KartausEntity e){return 0;}
 @Override public void render(KartausEntity e,float yaw,float partial,PoseStack p,MultiBufferSource b,int light){super.render(e,yaw,partial,p,b,light);float t=e.age(partial);if(e.action()==FalconAction.EYE&&t>=21&&t<=54){var at=Vec3.atBottomCenterOf(e.aim()).subtract(e.position());ring(p,b,at.x,at.y+.03,at.z,2.5,0xD62D3B,t>36?1:.7F);ring(p,b,at.x,at.y+.025,at.z,2.1,0xAB2B30,.6F);}if(e.action()==FalconAction.WAVE&&t<=33){var d=e.heading();for(int n=1;n<=14;n++)ring(p,b,d.x*n,.035,d.z*n,1.4,0xAB2B30,t>=19&&n<=(t-18)?1:.5F);}if(e.action()==FalconAction.CHAINS&&t>=8&&t<=28){var at=Vec3.atBottomCenterOf(e.aim()).subtract(e.position());ring(p,b,at.x,at.y+.03,at.z,2.5,0x6C2B9A,.8F);}if(e.action()==FalconAction.INTRO)ring(p,b,0,.03,0,2,0xAB2B30,.6F);if(e.action()==FalconAction.GUARDS&&t>=9&&t<=25)for(var q:e.guardPositions()){var at=Vec3.atBottomCenterOf(q).subtract(e.position());ring(p,b,at.x,at.y+.03,at.z,.7,0x6C2B9A,.7F);}}
 }
 public static class PropRenderer extends MobRenderer<BannerEntity,FinistModel<BannerEntity>>{private final FinistModel<BannerEntity> bannerModel=new FinistModel<>(BlackBannerMesh.create(),true),anchorModel=new FinistModel<>(CurseAnchorMesh.create(),true);public PropRenderer(EntityRendererProvider.Context c){super(c,new FinistModel<>(BlackBannerMesh.create(),true),0);}@Override public ResourceLocation getTextureLocation(BannerEntity e){return FinistContent.id("textures/entity/"+(e.anchor()?"kartaus_curse_anchor":"kartaus_banner")+".png");}@Override public void render(BannerEntity e,float yaw,float partial,PoseStack p,MultiBufferSource b,int l){model=e.anchor()?anchorModel:bannerModel;super.render(e,yaw,partial,p,b,l);}}
 @SubscribeEvent public static void hud(RenderGuiEvent.Post e){var m=Minecraft.getInstance();if(m.player==null||m.level==null||m.options.hideGui||m.screen!=null||!org.slavicmyths.bogatyr.BogatyrConfig.HUD.get())return;var f=m.level.getEntitiesOfClass(FinistEntity.class,m.player.getBoundingBox().inflate(48),a->m.player.getUUID().equals(a.syncedOwner())).stream().findFirst().orElse(null);if(f==null)return;var g=e.getGuiGraphics();int x=g.guiWidth()-155,y=g.guiHeight()-215;g.fill(x-3,y-3,x+145,y+42,0xCC182A49);g.drawString(m.font,f.getDisplayName(),x,y,0xEACB67);g.fill(x,y+13,x+138,y+18,0xFF473727);g.fill(x,y+13,x+Math.round(138*f.getHealth()/170),y+18,0xFFD0A64E);g.drawString(m.font,f.recovering()?net.minecraft.network.chat.Component.translatable("gui.slavicmyths.174.recovery"):net.minecraft.network.chat.Component.literal(Math.round(f.getHealth())+" / 170"),x,y+23,0xE5E0D1);if(f.bird()==4){g.drawString(m.font,net.minecraft.network.chat.Component.translatable("message.slavicmyths.falcon_cursed"),10,55,0xCF94EC);var a=m.level.getEntity(f.anchorId());if(a instanceof BannerEntity anchor)g.drawString(m.font,net.minecraft.network.chat.Component.translatable("gui.slavicmyths.174.anchor",Math.round(anchor.getHealth())),10,67,0xE5E0D1);}}
 private static void ring(PoseStack p,MultiBufferSource b,double x,double y,double z,double r,int c,float alpha){var v=b.getBuffer(RenderType.entityTranslucent(FinistContent.id("textures/entity/marinka_magic.png")));for(int i=0;i<32;i++){double a=i*Math.PI/16,xx=x+Math.cos(a)*r,zz=z+Math.sin(a)*r;double[][] q={{xx-.06,zz-.06},{xx+.06,zz-.06},{xx+.06,zz+.06},{xx-.06,zz+.06}};for(int j=0;j<4;j++)v.addVertex(p.last().pose(),(float)q[j][0],(float)y,(float)q[j][1]).setColor((c>>16&255)/255F,(c>>8&255)/255F,(c&255)/255F,alpha).setUv(j==0||j==3?0:1,j<2?0:1).setOverlay(OverlayTexture.NO_OVERLAY).setLight(0xF000F0).setNormal(p.last(),0,1,0);}}
}
